def gen(rng):
    def fmt(iv):
        return f"{len(iv)}\n" + '\n'.join(f'{s} {e}' for s, e in iv)

    def rnd(n, lo, hi, maxlen):
        out = []
        for _ in range(n):
            s = rng.randint(lo, hi)
            out.append((s, min(10**9, s + rng.randint(0, maxlen))))
        return out

    tests = [fmt([(5, 5)]), fmt([(1, 3), (3, 6), (5, 8)]), fmt([(1, 10**9), (1, 10**9), (10**9, 10**9)]), fmt([(1, 2), (3, 4), (5, 6)]), fmt([(2, 4), (1, 5), (3, 3), (4, 6)]), fmt([(1, 1), (2, 2), (1, 2)])]
    for n in (2, 3, 5, 8, 12, 20, 25):
        for _ in range(3):
            tests.append(fmt(rnd(n, 1, 30, rng.randint(0, 10))))
    n = 100000
    tests.append(fmt(rnd(n, 1, 10**9, 10**8)))
    tests.append(fmt(rnd(n, 1, 10**9 - 10, 10**9)))
    tests.append(fmt([(i + 1, i + 1) for i in range(n)]))
    tests.append(fmt([(1 + i, 10**9 - i) for i in range(n)]))
    tests.append(fmt(rnd(n, 1, 1000, 10)))
    return tests

